"The digit to the right of the rounding place decides.":"Decide el dígito a la derecha del lugar al que redondeas.",
"Round the cost of groceries to the nearest ten dollars and add in your head.":"Redondeen el costo de las compras a la decena de dólares más cercana y súmenlo mentalmente.",
