"Multiply by a {N}-digit number":"Multiplicar por un número de {N} dígito",
"Multiply each place, then add the parts.":"Multiplica cada lugar y luego suma las partes.",
"Split {N} into {N}, {N} and {N}.":"Separa {N} en {N}, {N} y {N}.",
"Multiply each part.":"Multiplica cada parte.",
"Add the parts together.":"Suma las partes.",
