"Multiply {N}-digit by {N}-digit":"Multiplicar {N} dígitos por {N} dígitos",
"Two {N}-digit numbers make a rectangle.":"Dos números de {N} dígitos forman un rectángulo.",
"Split both numbers into tens and ones.":"Separa ambos números en decenas y unidades.",
"Multiply all four parts.":"Multiplica las cuatro partes.",
"Add the four parts.":"Suma las cuatro partes.",
"How many parts does the area model have?":"¿Cuántas partes tiene el modelo de área?",
"Four parts: tens × tens, tens × ones, ones × tens, ones × ones.":"Cuatro partes: decenas × decenas, decenas × unidades, unidades × decenas, unidades × unidades.",
"Draw a rectangle for {N} × {N} on paper and fill in the four parts.":"Dibujen en papel un rectángulo para {N} × {N} y completen las cuatro partes.",
"Divide with remainders":"Dividir con residuo",
"Equal groups, with some left over.":"Grupos iguales, y sobran algunos.",
"Make as many equal groups as you can.":"Forma tantos grupos iguales como puedas.",
"What is left over is the remainder.":"Lo que sobra es el residuo.",
"The remainder is always smaller than the group size.":"El residuo siempre es menor que el tamaño del grupo.",
"How many groups fit?":"¿Cuántos grupos caben?",
"What is left?":"¿Qué sobra?",
"If what is left could make one more group, make it.":"Si con lo que sobra se puede formar otro grupo, fórmalo.",
"Share a bag of grapes among family members and talk about the leftovers.":"Repartan una bolsa de uvas entre la familia y hablen de las que sobran.",
"Divide by a {N}-digit number":"Dividir entre un número de {N} dígito",
