"Take away big easy chunks, like {N} or {N} groups.":"Quita trozos grandes y fáciles, como {N} o {N} grupos.",
"Keep taking chunks until nothing is left.":"Sigue quitando trozos hasta que no quede nada.",
"Add the chunks to get the answer.":"Suma los trozos para obtener la respuesta.",
"What easy chunk can you take away first?":"¿Qué trozo fácil puedes quitar primero?",
"Divide in friendly chunks, then add them.":"Divide en trozos amigables y luego súmalos.",
"Split ${N} equally among {N} people using tens first, then ones.":"Repartan ${N} en partes iguales entre {N} personas, primero las decenas y luego las unidades.",
"Factors and multiples":"Factores y múltiplos",
"Factors are the numbers that multiply to make it.":"Los factores son los números que, multiplicados, lo forman.",
"A factor divides with nothing left over.":"Un factor lo divide sin que sobre nada.",
"{N} is a factor of {N} because {N} × {N} = {N}.":"{N} es factor de {N} porque {N} × {N} = {N}.",
"Factors come in pairs.":"Los factores vienen en parejas.",
"Does it divide with nothing left?":"¿Lo divide sin que sobre nada?",
"Find the pair: what times this makes the number?":"Busca la pareja: ¿qué número por este da el número?",
"Arrange {N} or {N} coins into all the rectangles you can.":"Acomoden {N} o {N} monedas en todos los rectángulos que puedan.",
"Prime or composite":"Primo o compuesto",
"Some numbers can only make one rectangle.":"Algunos números solo pueden formar un rectángulo.",
"A prime number has exactly two factors: {N} and itself.":"Un número primo tiene exactamente dos factores: {N} y él mismo.",
"A composite number has more.":"Un número compuesto tiene más.",
"{N} is neither.":"El {N} no es ninguno de los dos.",
"Can you find a factor other than {N} and the number?":"¿Puedes hallar un factor distinto de {N} y del número?",
"Try {N}, {N}, {N} and {N}.":"Prueba con {N}, {N}, {N} y {N}.",
"Try to arrange {N} coins and then {N} coins into rectangles.":"Intenten acomodar {N} monedas y luego {N} monedas en rectángulos.",
"Which has more ways?":"¿Cuál tiene más formas?",
"Times as many":"Veces tanto",
"One pile can be a few times as big as another.":"Un montón puede ser varias veces más grande que otro.",
"\"{N} times as many\" means {N} equal groups.":"\"{N} veces tanto\" significa {N} grupos iguales.",
"Draw one bar, then {N} bars the same size.":"Dibuja una barra y luego {N} barras del mismo tamaño.",
"Multiply, or divide if the bigger amount is known.":"Multiplica, o divide si conoces la cantidad mayor.",
"Draw the smaller amount as one bar.":"Dibuja la cantidad menor como una barra.",
"Times as many means multiply.":"\"Veces tanto\" significa multiplicar.",
"Compare: \"My pencil is {N} cm.":"Comparen: \"Mi lápiz mide {N} cm.",
"Yours is {N} times as long.":"El tuyo es {N} veces más largo.",
"How long?\"":"¿Cuánto mide?\"",
"Number patterns":"Patrones numéricos",
"Find the rule and keep the pattern going.":"Encuentra la regla y continúa el patrón.",
"Look at how each number changes.":"Mira cómo cambia cada número.",
"Say the rule: add {N}, or multiply by {N}.":"Di la regla: sumar {N} o multiplicar por {N}.",
"Use the rule on the last number.":"Usa la regla con el último número.",
"How does each number change?":"¿Cómo cambia cada número?",
"Find the rule, then apply it once more.":"Encuentra la regla y aplícala una vez más.",
"Make a pattern with blocks and ask your child to say the rule and the next step.":"Hagan un patrón con bloques y pidan a su hijo que diga la regla y el paso siguiente.",
"Equivalent fractions":"Fracciones equivalentes",
"Different pieces, same amount.":"Pedazos distintos, misma cantidad.",
"Cut every piece into the same number of smaller pieces.":"Corta cada pedazo en la misma cantidad de pedazos más pequeños.",
"Multiply the top and bottom by the same number.":"Multiplica el número de arriba y el de abajo por el mismo número.",
"What did the bottom number get multiplied by?":"¿Por cuánto se multiplicó el número de abajo?",
"Do the same to the top and the bottom.":"Haz lo mismo arriba y abajo.",
"Fold paper strips into halves, quarters and eighths and line them up.":"Doblen tiras de papel en mitades, cuartos y octavos y alinéenlas.",
"Compare fractions":"Comparar fracciones",
"Which share is bigger?":"¿Qué porción es más grande?",
"Make the bottom numbers the same.":"Haz que los números de abajo sean iguales.",
"Then compare the tops.":"Luego compara los de arriba.",
"Same top?":"¿El de arriba es igual?",
"The smaller bottom is the bigger piece.":"El de abajo más pequeño es el pedazo más grande.",
"Can you make the bottoms match?":"¿Puedes hacer que los de abajo coincidan?",
"Make the bottom numbers match, then compare the tops.":"Haz que coincidan los números de abajo y luego compara los de arriba.",
"Cut two pizzas or paper plates into different parts and compare shares.":"Corten dos pizzas o platos de papel en partes distintas y comparen las porciones.",
"Add and subtract fractions":"Sumar y restar fracciones",
"Same-size pieces add up like counting.":"Los pedazos del mismo tamaño se suman como al contar.",
"The bottom number names the piece size.":"El número de abajo nombra el tamaño del pedazo.",
"Add or take away the tops.":"Suma o quita los de arriba.",
