"Count the pieces; the size does not change.":"Cuenta los pedazos; el tamaño no cambia.",
"Use measuring cups: {N}/{N} cup plus {N}/{N} cup is {N}/{N} cup.":"Usen tazas medidoras: {N}/{N} taza más {N}/{N} taza es {N}/{N} taza.",
