"Each whole is cut into the same pieces.":"Cada entero se corta en los mismos pedazos.",
"{N} {N}/{N}: {N} wholes are {N} quarters, plus {N} more.":"{N} {N}/{N}: {N} enteros son {N} cuartos, más {N}.",
