"Multiply fractions":"Multiplicar fracciones",
"A part of a part.":"Una parte de una parte.",
"Multiply the tops.":"Multiplica los de arriba.",
"Multiply the bottoms.":"Multiplica los de abajo.",
"Top times top, bottom times bottom.":"Arriba por arriba, abajo por abajo.",
"Multiply straight across.":"Multiplica en línea recta.",
