"How many pieces fit?":"¿Cuántos pedazos caben?",
"{N} ÷ {N}/{N}: each whole holds {N} quarters, so {N}.":"{N} ÷ {N}/{N}: cada entero tiene {N} cuartos, así que {N}.",
