"With a parent's consent, the app keeps a child's nickname and birth year, and a record of their answers: which skill, whether it was right, which hints they used, which strategy they chose and how long they took, plus how close their number-line warm-up estimates were, the badges they earned and the look they chose for Pip.":"Con el consentimiento de un padre o madre, la aplicación guarda el apodo y el año de nacimiento del niño, y un registro de sus respuestas: qué habilidad, si fue correcta, qué pistas usó, qué estrategia eligió y cuánto tardó, además de qué tan cerca estuvieron sus estimaciones en los calentamientos de la recta numérica, las insignias que ganó y el estilo que eligió para Pip.",
