"Builds on:":"Se apoya en:",
"Opens next:":"Abre después:",
"Place value is how our number system works.":"El valor posicional es cómo funciona nuestro sistema de números.",
"Written adding, subtracting and multiplying all lean on it.":"Sumar, restar y multiplicar por escrito se apoyan en él.",
"Adding and subtracting come up in almost every later topic, from money to fractions.":"Sumar y restar aparecen en casi todos los temas que vienen después, del dinero a las fracciones.",
"Multiplying and dividing are the base for fractions, area and most of Grades {N} and {N}.":"Multiplicar y dividir son la base de las fracciones, el área y casi todo {N}.º y {N}.º grado.",
"Word problems connect the math to real situations: choosing what to do, not only how to do it.":"Los problemas con historia conectan las matemáticas con situaciones reales: elegir qué hacer, no solo cómo hacerlo.",
"Patterns, expressions and mixed review keep skills connected and fresh.":"Los patrones, las expresiones y el repaso mixto mantienen las habilidades conectadas y frescas.",
"Fractions describe parts of a whole and lead to decimals and measurement.":"Las fracciones describen partes de un entero y llevan a los decimales y la medición.",
"Decimals extend place value past the ones place and are used for money and measuring.":"Los decimales extienden el valor posicional más allá de las unidades y se usan con el dinero y al medir.",
"Counting money uses place value and adding in a setting children meet every day.":"Contar dinero usa el valor posicional y la suma en una situación que los niños viven a diario.",
"Reading clocks and finding time passed use counting by {N}s and the {N} minutes in an hour.":"Leer relojes y calcular el tiempo que pasó usan contar de {N1} en {N1} y los {N2} minutos de una hora.",
"Measuring connects numbers to real lengths, and area is a picture of multiplying.":"Medir conecta los números con longitudes reales, y el área es un dibujo de la multiplicación.",
"Shapes, angles and grids are the start of geometry and of reading graphs and maps.":"Las figuras, los ángulos y las cuadrículas son el comienzo de la geometría y de leer gráficas y mapas.",
